import { Component } from '@angular/core';
import { Form, GenericFormComponent } from "../../../shared/generic-form/generic-form.component";
import { ActivatedRoute } from '@angular/router';
import { DespachoService } from '../../../controllers/despacho.service';
import { Despacho } from '../../../models/despacho.model';

const FORM_DEF:Form=[
  {
    title:'Datos Generales',
    fields:[
      {
        key:'nombre',
        label:'Nombre del Despacho',
        type:'text',
      },
      {
        key:'rfc',
        label:'RFC',
        type:'text',
      },
      {
        key:'domicilio',
        label:'Domicilio del Despacho',
        type:'text',
      },
    ]
  },
  {
    title:'Representantes Legales',
    foreign_key:'despacho_id',
    apiUrl:'api/despachos_representantes_legales',
    baseFields:[
      {
        key:'nombre',
        label:'Nombre',
        type:'text'
      },
      {
        key:'correo',
        label:'Correo',
        type:'text'
      },
      {
        key:'telefono',
        label:'Teléfono',
        type:'text'
      },
    ]
  },
  {
    title:'Teléfonos del Despacho',
    foreign_key:'despacho_id',
    apiUrl:'api/despachos_telefonos',
    baseFields:[
      {
        key:'telefono',
        label:'Teléfono',
        type:'text'
      },
      {
        key:'tipo',
        label:'Tipo Teléfono',
        options:['CASA','CELULAR','OFICINA','OTRO']
      },
    ]
  },
]

@Component({
    selector: 'app-form-despachos',
    imports: [
        GenericFormComponent
    ],
    templateUrl: './form-despachos.component.html',
    styleUrl: './form-despachos.component.css'
})
export class FormDespachosComponent {
  edit?:Despacho
  form=FORM_DEF

  constructor(
    public despachoController: DespachoService,
    private route:ActivatedRoute,
  ){}

  ngOnInit(){
    this.route.params.subscribe(async (params)=>{
      if(params['despacho_id']){
        this.edit= await this.despachoController.find(params['despacho_id'])
      }
    })
  }
}
